), lagged as (
  select g.*, case when metric_name like '%yoy' then 1 when metric_name like '%3y%' then 3 else 5 end lag from g
), withprior as (
  select l.*, (select cf.value from analytics.canonical_fact cf join core.period p on p.id=cf.period_id
                join analytics.canonical_concept c2 on c2.id=cf.canonical_concept_id
               where cf.company_id=l.company_id and c2.name=l.concept and p.fiscal_period='FY'
                 and p.fiscal_year = (select p2.fiscal_year from core.period p2 where p2.company_id=l.company_id and p2.end_date=l.period_end and p2.fiscal_period='FY' limit 1) - l.lag
               limit 1) prior,
         (select cf.value from analytics.canonical_fact cf join core.period p on p.id=cf.period_id
                join analytics.canonical_concept c2 on c2.id=cf.canonical_concept_id
               where cf.company_id=l.company_id and c2.name=l.concept and p.fiscal_period='FY' and p.end_date=l.period_end limit 1) cur
  from lagged l where l.period_end >= date '2024-06-01'
