select metric_name, count(*) rows_valued, count(*) filter (where prior<0) prior_negative,
       count(*) filter (where prior<0 and cur<0) both_negative,
       count(*) filter (where prior<0 and cur>0) neg_to_pos
from withprior group by metric_name order by 1;
